function calculateSize(linesChanged) {
  if (linesChanged < 10) return 'size/XS';
  if (linesChanged < 50) return 'size/S';
  if (linesChanged < 250) return 'size/M';
  if (linesChanged < 1000) return 'size/L';
  return 'size/XL';
}

