# doc: Every glob for the named groups, de-duplicated, in a stable order.      "all" expands to every group. An unknown name raises ValueError naming the     valid ones -- argparse `choices` already rejects it at the CLI, so this is     for the Python API.
def globs_for(names: list[str] | tuple[str, ...]) -> list[str]:
    """Every glob for the named groups, de-duplicated, in a stable order.

    "all" expands to every group. An unknown name raises ValueError naming the
    valid ones -- argparse `choices` already rejects it at the CLI, so this is
    for the Python API.
    """
    wanted: list[str] = []
    for name in names:
        if name == "all":
            wanted.extend(GROUP_NAMES)
        elif name in GROUPS:
            wanted.append(name)
        else:
            raise ValueError(
                f"unknown exclusion group {name!r}; choose from {', '.join(GROUP_NAMES)}, all"
            )

    seen: set[str] = set()
    out: list[str] = []
    for name in wanted:
        for glob in GROUPS[name].globs:
            if glob not in seen:
                seen.add(glob)
                out.append(glob)
    return out

