# doc: Explain a node, its metadata, incoming/outgoing edges, and chunks.
def explain_node(outdir: Path, node_id: str) -> dict[str, Any]:
    """Explain a node, its metadata, incoming/outgoing edges, and chunks."""
    idx = Index(outdir)
    node = idx.store.node(node_id)
    if node is None:
        return {
            "found": False,
            "node_id": node_id,
            "reason": f"node '{node_id}' does not exist in graph",
        }

    in_edges = []
    out_edges = []
    for other, etype, direction, edge in idx.store.neighbours(node_id):
        if direction == "in":
            in_edges.append(edge)
        else:
            out_edges.append(edge)

    chunks = [
        {
            "id": c.get("id"),
            "kind": c.get("kind"),
            "start_line": c.get("start_line"),
            "end_line": c.get("end_line"),
            "char_len": len(c.get("text") or ""),
        }
        for c in idx.by_node.get(node_id, [])
    ]

    return {
        "found": True,
        "node_id": node_id,
        "node": node,
        "in_degree": len(in_edges),
        "out_degree": len(out_edges),
        "in_edges": in_edges,
        "out_edges": out_edges,
        "chunks": chunks,
    }

