# calls (outside the repo): append, len
def _reverse_closure(
    index: Index, seed: str, etype: str, max_hops: int, visited_cap: int
) -> tuple[dict[str, int], bool]:
    dist: dict[str, int] = {}
    seen = {seed}
    frontier = [seed]
    truncated = False
    hop = 0
    while frontier and hop < max_hops:
        hop += 1
        nxt: list[str] = []
        for nid in frontier:
            for dst, et, direction, _edge in index.store.neighbours(nid):
                if et != etype or direction != "in" or dst in seen:
                    continue
                if _path_secret(index, dst):
                    continue
                seen.add(dst)
                dist[dst] = hop
                nxt.append(dst)
                if len(seen) > visited_cap:
                    truncated = True
                    nxt = []
                    break
            if truncated:
                break
        frontier = nxt
    return dist, truncated

