# calls (outside the repo): findall, len, set, lower, list, split, discard
# doc: Apply multiplier to BM25 scores for chunks matching query identifier names.
    def _boost_identifiers(self, query: str, acc: dict[int, float]) -> None:
        """Apply multiplier to BM25 scores for chunks matching query identifier names."""
        # IDENT_RE supports single-character identifier names, minus the
        # English words `a` and `I` (see `_single_char_idents`):
        idents = {t for t in IDENT_RE.findall(query) if len(t) > 1}
        idents |= set(_single_char_idents(query))
        if not idents:
            return
        lowered = {t.lower() for t in idents}
        for i in list(acc):
            c = self.chunks[i]
            qual = c.get("qualname") or ""
            names = {c.get("name") or "", QUALNAME_SEP_RE.split(qual)[-1] if qual else ""}
            names.discard("")
            if not names:
                continue
            if names & idents or {n.lower() for n in names} & lowered:
                acc[i] *= IDENT_BOOST

