                return truncated_list
            return [sanitize_value(key, v, depth=depth + 1, seen=seen) for v in value]

        if isinstance(value, set):
            s_list = sorted(str(x) for x in value)
            return sanitize_value(key, s_list, depth=depth, seen=seen)

