# calls (outside the repo): isinstance, fromisoformat, replace, max, int, total_seconds, now
# doc: Seconds since `created_at`, or None when it is absent or unparseable.
def _age_seconds(created_at: Any) -> int | None:
    """Seconds since `created_at`, or None when it is absent or unparseable."""
    if not isinstance(created_at, str) or not created_at:
        return None
    try:
        when = datetime.fromisoformat(created_at)
    except ValueError:
        return None
    if when.tzinfo is None:
        when = when.replace(tzinfo=timezone.utc)
    return max(0, int((datetime.now(timezone.utc) - when).total_seconds()))

