def score_to_grade(score: int | float) -> str:
    """Convert numeric score (0-100) to standard letter grade."""
    if score >= 93:
        return "A"
    if score >= 88:
        return "A-"
    if score >= 83:
        return "B+"
    if score >= 78:
        return "B"
    if score >= 70:
        return "B-"
    if score >= 65:
        return "C+"
    if score >= 60:
        return "C"
    if score >= 50:
        return "D"
    return "F"

