def _find(edges, etype, src=None, dst=None):
    for e in edges:
        if e["type"] != etype:
            continue
        if src and e["src"] != src:
            continue
        if dst and e["dst"] != dst:
            continue
        return e
    raise AssertionError(f"no {etype} edge matching src={src} dst={dst}")

