def test_parse_javascript_extracts_symbols_calls_and_imports():
    source = b"""\
import { helper } from "./helper.js";

function greet(name) {
    return helper(name);
}

class Runner {
    run(value) {
        return greet(value);
    }
}

const wrap = (value) => helper(value);
"""
