# calls (outside the repo): bytearray, append, bytes
def uvarint(n: int) -> bytes:
    out = bytearray()
    n &= (1 << 64) - 1  # int32/int64 negatives travel sign-extended
    while True:
        b, n = n & 0x7F, n >> 7
        out.append(b | 0x80 if n else b)
        if not n:
            return bytes(out)

