# doc: A drop-in for threading.Lock (which rejects attribute assignment)     that counts how many times it was actually held.
class RecordingLock:
    """A drop-in for threading.Lock (which rejects attribute assignment)
    that counts how many times it was actually held."""

    def __init__(self):
        self._real = threading.Lock()
        self.acquisitions = 0

    def acquire(self, *a, **k):
        self.acquisitions += 1
        return self._real.acquire(*a, **k)

    def release(self):
        self._real.release()

    def __enter__(self):
        self.acquire()
        return self

    def __exit__(self, *exc):
        self.release()

